using UnityEngine;
using Kamilunavo.RepairEmpire.Visuals;
namespace Kamilunavo.RepairEmpire.Gameplay {
 public sealed class CityBuilder:MonoBehaviour {
  public Transform Destination;Transform arrows,world;RepairGame game;
  Material asphalt,concrete,stone,navy,orange,glass,steel,leaf,wood,white,cyan;
  public void Build(){world=new GameObject("Authored static district").transform;world.SetParent(transform,false);Random.InitState(261008);asphalt=Surface("CityAsphalt",0,2,new(.82f,.82f,.82f));concrete=Surface("CityPaving",1,2.2f,new(.92f,.94f,.96f));stone=Surface("CityStone",2,1.8f,new(.90f,.93f,.94f));navy=MeshArt.Mat("CityNavy",new(.025f,.07f,.105f));orange=MeshArt.Mat("CityOrange",new(1,.32f,.045f));glass=Surface("CityGlazing",3,5,new(.75f,.88f,1),.45f,.78f);glass.SetFloat("_Metallic",.62f);glass.SetFloat("_Glossiness",.85f);steel=MeshArt.Mat("CityMetal",new(.13f,.19f,.23f));leaf=MeshArt.Mat("CityLeaves",Color.white);leaf.shader=Resources.Load<Shader>("Foliage");leaf.mainTexture=Resources.Load<Texture2D>("Art/TreeCanopy");leaf.SetFloat("_Cutoff",.42f);wood=MeshArt.Mat("CityWood",new(.31f,.23f,.12f));white=MeshArt.Mat("CityLines",new(.96f,.93f,.82f));cyan=MeshArt.Mat("RouteCyan",new(.04f,.78f,1),-1,true);
   var ground=Box("Continuous driveable ground",new(0,-.3f,220),new(150,.5f,510),concrete,true);
   foreach(float x in new[]{0f,-32f,32f}){float width=x==0?16:12;Box("Asphalt avenue",new(x,-.035f,220),new(width,.025f,470),asphalt);foreach(int side in new[]{-1,1}){Box("Low pavement",new(x+side*(width/2+1.8f),0,220),new(3.6f,.05f,470),concrete);for(int z=4;z<450;z+=8)Box("Pavement joint",new(x+side*(width/2+1.8f),.028f,z),new(3.5f,.008f,.014f),stone);}for(int z=4;z<450;z+=10)if(!AtJunction(z))Box("Lane dash",new(x,.002f,z),new(.1f,.01f,3.2f),white);}
   foreach(float z in new[]{96f,220f,340f}){Box("Cross street",new(0,.004f,z),new(92,.025f,10),asphalt);for(int side=-1;side<=1;side+=2)for(int i=0;i<7;i++)Box("Crosswalk",new(-6+i*2,.02f,z+side*6.5f),new(1.1f,.02f,2.1f),white);}
   for(int z=14;z<445;z+=24){if(AtJunction(z,17))continue;foreach(float x in new[]{-18f,18f,-49f,49f}){if(x==18&&z<62)continue;Building(x,z,Random.Range(12,30),x>0?-1:1);}}
   for(int z=12;z<435;z+=25){if(AtJunction(z,12))continue;foreach(int side in new[]{-1,1}){Tree(new(side*11.2f,0,z));Lamp(new(side*8.9f,0,z+9));Box("Planter",new(side*11.2f,.2f,z),new(1.5f,.4f,1.5f),stone);}}
   StreetDetails();Workshop();MeshArt.Batch(world.gameObject);var env=new GameObject("Route and customer marker").transform;env.SetParent(transform,false);arrows=new GameObject("Directional cyan chevrons").transform;arrows.SetParent(env,false);for(int i=0;i<10;i++){var arrow=new GameObject("Route chevron").transform;arrow.SetParent(arrows,false);foreach(int side in new[]{-1,1}){var arm=MeshArt.Box(arrow,"Chevron arm",new(side*.34f,.04f,-.27f),new(.16f,.035f,.84f),cyan);arm.transform.localRotation=Quaternion.Euler(0,side*44,0);}}
   Destination=new GameObject("Service address pin").transform;Destination.SetParent(env,false);MeshArt.Lathe(Destination,"Orange pin",new[]{0f,.55f,1.05f,1.55f},new[]{0f,.32f,.55f,.18f},12,orange,Vector3.one);MeshArt.Oval(Destination,"Pin center",new(0,1.0f,-.12f),new(.24f,.24f,.24f),white);var ring=MeshArt.Ring(Destination,"Address circle",1.5f,.1f,-1.9f,orange,40);
   var sky=new Material(Shader.Find("Repair/Sky"));sky.mainTexture=Resources.Load<Texture2D>("Art/SkyPanorama");RenderSettings.skybox=sky;ArtLifetime.Own(gameObject,sky);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Trilight;RenderSettings.ambientSkyColor=new(.49f,.60f,.72f);RenderSettings.ambientEquatorColor=new(.32f,.38f,.43f);RenderSettings.ambientGroundColor=new(.18f,.20f,.22f);RenderSettings.fog=true;RenderSettings.fogColor=new(.65f,.79f,.91f);RenderSettings.fogMode=FogMode.Linear;RenderSettings.fogStartDistance=170;RenderSettings.fogEndDistance=430;
  }
  static Material Surface(string key,int tile,float metres,Color tint,float metallic=0,float smoothness=.2f){var mat=MeshArt.Mat(key,tint);mat.shader=Resources.Load<Shader>("CitySurface");mat.SetTexture("_CityTiles",Resources.Load<Texture2DArray>("Art/WorldSurfaceArray"));mat.SetFloat("_AtlasTile",tile);mat.SetFloat("_MetersPerTile",metres);mat.SetFloat("_Metallic",metallic);mat.SetFloat("_Glossiness",smoothness);return mat;}
  public void Bind(RepairGame owner){game=owner;}
  void Update(){if(game==null||arrows==null)return;var job=game.ActiveJob;arrows.gameObject.SetActive(job!=null);Destination.gameObject.SetActive(job!=null);if(job==null)return;Destination.position=new(job.DestinationX,2,job.DestinationZ);var from=game.Vehicle.transform.position;var direction=new Vector3(job.DestinationX-from.x,0,job.DestinationZ-from.z);if(direction.sqrMagnitude<.01f)return;var rot=Quaternion.LookRotation(direction.normalized);for(int i=0;i<arrows.childCount;i++){var a=arrows.GetChild(i);a.position=new Vector3(from.x,0,from.z)+direction.normalized*(6+i*3);a.rotation=rot;a.gameObject.SetActive(6+i*3<direction.magnitude);}}
  static bool AtJunction(float z,float radius=9){foreach(float c in new[]{96f,220f,340f})if(Mathf.Abs(z-c)<radius)return true;return false;}
  GameObject Box(string name,Vector3 position,Vector3 scale,Material material,bool collider=false){var go=MeshArt.Box(world,name,position,scale,material);if(collider){var c=go.AddComponent<BoxCollider>();c.center=Vector3.zero;c.size=scale;}return go;}
  void Building(float x,float z,float h,int facing){var tint=Surface("Facade"+((int)h%4),2,2,new(.80f+.04f*((int)h%4),.86f+.03f*((int)h%4),.91f+.02f*((int)h%4)));float width=Mathf.Abs(x)>30?13:10,depth=17;Box("Concrete building core",new(x,h/2,z),new(width,h,depth),tint,true);Box("Roof crown",new(x,h+.18f,z),new(width+.35f,.35f,depth+.35f),stone);float front=x+facing*(width/2+.025f);for(int floor=1;floor<h/3;floor++){float y=floor*3.05f;for(int col=0;col<5;col++){float zz=z-6.5f+col*3.1f;Box("Reflective glass pane",new(front,y,zz),new(.035f,2.30f,2.62f),glass);Box("Window mullion",new(front+facing*.03f,y,zz+1.35f),new(.09f,2.4f,.065f),steel);}Box("Facade floor band",new(front+facing*.04f,y-1.3f,z),new(.13f,.1f,depth),stone);}Box("Storefront glazing",new(front,1.25f,z),new(.04f,2.25f,depth-1.2f),glass);Box("Shop canopy",new(front+facing*.65f,2.66f,z),new(1.35f,.16f,depth-1),navy);for(int i=0;i<4;i++)Box("Entrance frame",new(front+facing*.08f,1.2f,z-5.6f+i*3.75f),new(.12f,2.4f,.09f),steel);Box("Rooftop plant",new(x,h+.6f,z+3),new(2.5f,1.2f,3.3f),steel);
   // Return elevations face the driving camera at corners, so they receive real windows and trim too.
   foreach(int end in new[]{-1,1}){float faceZ=z+end*(depth/2+.03f);for(int floor=1;floor<h/3;floor++){float y=floor*3.05f;for(int col=0;col<3;col++)Box("Corner return glazing",new(x+(col-1)*(width*.29f),y,faceZ),new(width*.23f,2.25f,.045f),glass);Box("Return stone floor band",new(x,y-1.3f,faceZ+end*.025f),new(width+.06f,.13f,.10f),stone);}Box("Return ground glazing",new(x,1.24f,faceZ),new(width-1.1f,2.15f,.045f),glass);foreach(int edge in new[]{-1,1})Box("Corner stone pilaster",new(x+edge*(width/2-.12f),h/2,faceZ),new(.24f,h,.14f),stone);}
   var signMat=MeshArt.Mat("StoreSign"+((int)z%3),new[]{new Color(.06f,.23f,.28f),new Color(.32f,.17f,.08f),new Color(.13f,.25f,.15f)}[(int)z%3]);Box("Neighbourhood shop sign",new(front+facing*.15f,2.78f,z),new(.12f,.53f,5.3f),signMat);VanArt.Text(world,new[]{"MARKT","CAFÉ","CITY LOFTS"}[(int)z%3],new(front+facing*.23f,2.78f,z),.19f,Color.white,Quaternion.Euler(0,facing<0?90:-90,0));}
  void StreetDetails(){var soil=MeshArt.Mat("PlanterSoil",new(.12f,.10f,.065f));var seat=MeshArt.Mat("BenchSlats",new(.39f,.24f,.12f));for(int z=20;z<420;z+=50){if(AtJunction(z,16))continue;foreach(int side in new[]{-1,1}){float x=side*10.6f;Box("Street bench seat",new(x,.50f,z),new(.68f,.09f,1.9f),seat);Box("Street bench back",new(x+side*.32f,.84f,z),new(.07f,.61f,1.9f),seat);foreach(int leg in new[]{-1,1})Box("Bench metal leg",new(x,.26f,z+leg*.72f),new(.55f,.48f,.09f),steel);Box("Litter bin",new(x,.42f,z+2.4f),new(.48f,.84f,.48f),navy);Box("Bin opening",new(x-side*.245f,.68f,z+2.4f),new(.018f,.16f,.32f),steel);Box("Planter soil",new(side*11.2f,.411f,z-8),new(1.28f,.015f,1.28f),soil);}}
   foreach(float z in new[]{96f,220f,340f})foreach(int side in new[]{-1,1}){float x=side*9.8f;Box("Traffic signal pole",new(x,1.65f,z-8),new(.10f,3.3f,.10f),steel);Box("Traffic signal housing",new(x,3.05f,z-8),new(.38f,.94f,.28f),navy);for(int light=0;light<3;light++){var col=light==0?new Color(.62f,.08f,.04f):light==1?new Color(.43f,.28f,.03f):new Color(.03f,.72f,.28f);MeshArt.Oval(world,"Signal lens",new(x,3.35f-light*.29f,z-8.16f),new(.19f,.19f,.025f),MeshArt.Mat("Signal"+light,col,-1,light==2));}}
  }
  void Tree(Vector3 p){var root=new GameObject("Street tree").transform;root.SetParent(world,false);root.localPosition=p;MeshArt.Lathe(root,"Trunk",new[]{0f,2.5f,3.2f},new[]{.13f,.10f,.04f},7,wood,Vector3.one);for(int i=0;i<3;i++){var crown=MeshArt.Mesh(root,"Detailed leaf canopy",new[]{new Vector3(-1.8f,-1.7f,0),new Vector3(1.8f,-1.7f,0),new Vector3(1.8f,1.7f,0),new Vector3(-1.8f,1.7f,0)},new[]{0,2,1,0,3,2},new[]{new Vector2(0,0),new Vector2(1,0),new Vector2(1,1),new Vector2(0,1)},leaf);crown.transform.localPosition=new(0,3.55f,0);crown.transform.localRotation=Quaternion.Euler(0,i*60,0);}}
  void Lamp(Vector3 p){var root=new GameObject("Street light").transform;root.SetParent(world,false);root.localPosition=p;MeshArt.Lathe(root,"Lamp pole",new[]{0f,.18f,4.8f},new[]{.16f,.11f,.075f},8,steel,Vector3.one);MeshArt.Box(root,"Lamp arm",new(.43f,4.78f,0),new(.85f,.1f,.09f),steel);MeshArt.Box(root,"Lamp housing",new(.85f,4.75f,0),new(.5f,.1f,.28f),navy);}
  void Workshop(){Box("Workshop rear wall",new(25,3.5f,35),new(.3f,7,20),navy,true);foreach(int side in new[]{-1,1})Box("Workshop side wall",new(19,3.5f,35+side*10),new(12,7,.3f),stone,true);Box("Workshop roof",new(19,7,35),new(12.4f,.3f,20.4f),navy);Box("Workshop fascia",new(12.8f,5.7f,35),new(.32f,2.2f,20),navy);Box("Orange garage lintel",new(12.55f,4.35f,35),new(.3f,.35f,20),orange);VanArt.Text(world,"REPAIR",new(12.5f,6.2f,35),.90f,Color.white,Quaternion.Euler(0,90,0));VanArt.Text(world,"EMPIRE",new(12.5f,5.20f,35),.90f,new(1,.32f,.045f),Quaternion.Euler(0,90,0));for(int i=0;i<4;i++){Box("Garage pillar",new(12.8f,2.05f,25+i*6.65f),new(.6f,4.1f,.5f),navy,true);Box("Safety bollard",new(11.8f,.62f,25+i*6.65f),new(.25f,1.25f,.25f),orange);}for(int i=0;i<4;i++){Box("Tool cabinet",new(24,1,28+i*4),new(1.2f,2,2.1f),steel);for(int j=0;j<5;j++)Box("Cabinet drawer",new(23.36f,.25f+j*.3f,28+i*4),new(.025f,.07f,1.85f),orange);}for(int i=0;i<3;i++)Box("Garage ceiling light",new(19,6.7f,29+i*6),new(5,.07f,.22f),MeshArt.Mat("WorkshopLight",new(1,.89f,.65f),-1,true));}
 }
